// src/pages/Dashboard/Sections/Perfil.tsx
import React, { useState } from "react";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
} from "recharts";
import { User } from "firebase/auth";

interface PerfilProps {
  user: User;
}

const dataEjemplo = [
  { semana: "01-07", horas: 5 },
  { semana: "08-14", horas: 12 },
  { semana: "15-21", horas: 7 },
  { semana: "22-28", horas: 13 },
];

const horariosSemana = [
  { día: "Lunes", hora: "18:00 - 20:00" },
  { día: "Miércoles", hora: "19:00 - 21:00" },
  { día: "Viernes", hora: "17:00 - 19:00" },
];

const Perfil: React.FC<PerfilProps> = ({ user }) => {
  const [mesSeleccionado, setMesSeleccionado] = useState("2025-05");

  return (
    <div className="flex flex-col md:flex-row gap-6 p-6 bg-neutral-900 text-white min-h-screen">
      {/* Sidebar */}
      <aside className="md:w-1/3 flex flex-col items-center bg-neutral-800 rounded-lg p-4 shadow-lg">
        <img
          src="https://i.pravatar.cc/150?img=3"
          alt="Avatar"
          className="w-32 h-32 rounded-full mb-4 shadow-md"
        />
        <div className="space-y-2 text-center">
          <p>
            <strong>Nombre de Usuario:</strong>
            <br />
            {user.displayName || "Sin nombre"}
          </p>
          <p>
            <strong>ID del Usuario:</strong>
            <br />@{user.uid}
          </p>
          <p>
            <strong>Email:</strong>
            <br />
            {user.email}
          </p>
          <p>
            <strong>Miembro desde:</strong>
            <br />
            {user.metadata?.creationTime
              ? new Date(user.metadata.creationTime).toLocaleDateString()
              : "Desconocido"}
          </p>
        </div>
      </aside>

      {/* Main content */}
      <main className="flex-1 space-y-6">
        {/* Selector de mes */}
        <div className="flex items-center gap-4">
          <label htmlFor="mes" className="font-semibold">
            Selecciona el mes:
          </label>
          <input
            id="mes"
            type="month"
            value={mesSeleccionado}
            onChange={(e) => setMesSeleccionado(e.target.value)}
            className="bg-neutral-800 text-white p-2 rounded-md outline-none border border-neutral-700"
          />
        </div>

        {/* Horarios */}
        <div className="bg-neutral-800 rounded-lg p-4 shadow-md">
          <h3 className="text-lg font-bold mb-2">
            Horarios generados esta semana
          </h3>
          <table className="w-full text-sm text-left">
            <thead>
              <tr className="border-b border-neutral-700">
                <th className="py-2">Día</th>
                <th className="py-2">Horario</th>
              </tr>
            </thead>
            <tbody>
              {horariosSemana.map((h, i) => (
                <tr key={i} className="hover:bg-neutral-700 transition">
                  <td className="py-2">{h.día}</td>
                  <td className="py-2">{h.hora}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Gráfico */}
        <div className="bg-neutral-800 rounded-lg p-4 shadow-md">
          <h3 className="text-lg font-bold mb-4">
            Horas jugadas en {mesSeleccionado}
          </h3>
          <div className="w-full h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={dataEjemplo}>
                <XAxis dataKey="semana" stroke="#fff" />
                <YAxis stroke="#fff" />
                <Tooltip
                  contentStyle={{ backgroundColor: "#333", border: "none" }}
                />
                <Bar dataKey="horas" fill="#3b82f6" />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </main>
    </div>
  );
};

export default Perfil;
